#include <bits/stdc++.h>
using namespace std; using U=uint64_t; mt19937 gen(138); int n; U a[64]; long long evals=0;
bool cycle(U s){int p[64];iota(p,p+64,0);auto root=[&](int v){while(p[v]!=v)v=p[v];return v;};for(U q=s;q;q&=q-1){int v=__builtin_ctzll(q);U t=a[v]&s&(~0ULL<<(v+1));for(;t;t&=t-1){int w=__builtin_ctzll(t),x=root(v),y=root(w);if(x==y)return true;p[x]=y;}}return false;}
int score(){evals++;int bad=0;U full=(1ULL<<n)-1;for(int i=0;i<n;i++){int d=__builtin_popcountll(a[i]);bad+=max(0,4-d)*5;if((a[i]|(1ULL<<i))!=full&&!cycle(a[i]))bad++;for(int j=0;j<i;j++){U s=(1ULL<<i)|(1ULL<<j),b=(a[i]|a[j])&~s;if((b|s)!=full&&!cycle(b))bad++;}}return bad;}
bool conn(U s){if(!s)return true;U seen=s&-s,prev=0;while(seen!=prev){prev=seen;for(U q=seen;q;q&=q-1)seen|=a[__builtin_ctzll(q)]&s;}return seen==s;}
bool four(){U full=(1ULL<<n)-1;for(int i=0;i<n;i++)for(int j=0;j<i;j++)for(int k=0;k<j;k++)if(!conn(full&~((1ULL<<i)|(1ULL<<j)|(1ULL<<k))))return false;return true;}
void flip(int i,int j){a[i]^=1ULL<<j;a[j]^=1ULL<<i;}
int main(int argc,char**argv){n=atoi(argv[1]);int rounds=atoi(argv[2]),m=(7*n+2)/3-1,best=1000,hits=0;vector<pair<int,int>> pairs;for(int i=0;i<n;i++)for(int j=0;j<i;j++)pairs.emplace_back(i,j);
for(int run=0;run<rounds;run++){fill(a,a+64,0);shuffle(pairs.begin(),pairs.end(),gen);for(int t=0;t<m;t++)flip(pairs[t].first,pairs[t].second);int s=score();for(int it=0;it<20000;it++){int x=gen()%m,y=m+gen()%(pairs.size()-m);auto e=pairs[x],f=pairs[y];flip(e.first,e.second);flip(f.first,f.second);int z=score();double temp=.08+1.5*(1.-(it%5000)/5000.);if(z<=s||generate_canonical<double,32>(gen)<exp((s-z)/temp)){s=z;swap(pairs[x],pairs[y]);}else{flip(e.first,e.second);flip(f.first,f.second);}if(s<best){best=s;cout<<"n "<<n<<" m "<<m<<" run "<<run<<" iter "<<it<<" best "<<best<<" evals "<<evals<<endl;}if(s==0){hits++;if(four()){cout<<"COUNTEREXAMPLE\n";for(int i=0;i<n;i++)for(int j=0;j<i;j++)if(a[i]>>j&1)cout<<i<<","<<j<<" ";cout<<endl;return 0;}break;}}}cout<<"END n "<<n<<" rounds "<<rounds<<" evals "<<evals<<" cyclic_hits "<<hits<<" best "<<best<<endl;}
